window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/linguagens_2024.js"]=[{"title":"Adversidade não precisa impedir oportunidades","steps":["Einstein associa dificuldade a oportunidade, desordem a simplicidade e discordância a harmonia.","Marley contrasta apenas sentir a chuva com conseguir experimentar algo positivo nela.","As citações convergem em aproveitar situações potencialmente adversas, C, e não simplesmente evitá-las."],"alternatives":{"A":"Os textos não pedem ajuda a outras pessoas em situação de necessidade.","B":"Não ensinam a reconhecer perigos; sugerem modos de lidar com dificuldades.","C":"As duas frases valorizam a possibilidade de encontrar algo positivo em condições adversas.","D":"Evitar as dificuldades contraria encontrar oportunidade no interior delas.","E":"Não há crítica às situações harmoniosas, mas transformação da perspectiva diante do problema."},"takeaway":"Procure a ideia comum entre textos diferentes, não uma tradução isolada de uma palavra.","key":"linguagens:L492","area":"linguagens","year":2024,"number":1,"answer":"C","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[2,3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Instead of propõe uma substituição","steps":["Instead of significa em vez de.","A canção contrapõe amar e cuidar a polir as bombas de uma guerra.","O conector pede troca de atitude, portanto introduz mudança de comportamento, A."],"alternatives":{"A":"A expressão substitui uma conduta hostil por amar e cuidar mais do outro.","B":"O conflito é o contexto geral, mas o marcador introduz a alternativa a ele.","C":"O isolamento aparece antes e é criticado, não proposto depois do marcador.","D":"A perspectiva bélica é o que deve ser substituído, não o comportamento recomendado.","E":"Holy war integra a imagem criticada; não é a função do conector."},"takeaway":"Traduza conectores dentro da relação lógica que estabelecem entre ações.","key":"linguagens:L493","area":"linguagens","year":2024,"number":2,"answer":"A","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[2,4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A natureza apagada como um arquivo","steps":["A imagem imita uma janela de exclusão, com a indicação 70% Deleted.","Os ícones mostram a eliminação de árvores e a taxa e o tempo restantes sugerem continuidade acelerada.","A metáfora digital alerta para a rápida destruição da natureza, A, sem ensinar um procedimento de informática."],"alternatives":{"A":"Apagar a natureza como arquivos torna visível e criticável a velocidade da destruição.","B":"O tempo é usado para dimensionar uma perda ambiental, não é o tema isolado.","C":"Não se anunciam ferramentas agrícolas nem aumento de produtividade.","D":"A janela é uma metáfora crítica; não é um manual de uso sustentável de aparelhos.","E":"A contagem se refere à destruição, não ao crescimento ou reposição das árvores."},"takeaway":"Leia números, ícones e comandos como elementos de uma mensagem crítica multimodal.","key":"linguagens:L494","area":"linguagens","year":2024,"number":3,"answer":"A","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[2,4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma identidade reprimida pelo sotaque","steps":["A narradora é repreendida por falar espanhol e por tentar ensinar a pronúncia de seu nome.","A mãe e a universidade também pressionam pela eliminação do sotaque mexicano.","O prejuízo descrito é o repúdio ao sotaque espanhol no uso do inglês, A."],"alternatives":{"A":"A exigência de get rid of our accents explicita a repressão às marcas linguísticas de origem.","B":"O texto denuncia e recorda a pressão, não apresenta resignação como causa do problema.","C":"Não se pede mais oferta de aulas de espanhol; a questão é discriminação.","D":"Há diferentes gerações, mas professores e universidade também reproduzem a rejeição.","E":"Não é uma competição neutra de variedades, e sim uma hierarquia que inferioriza o sotaque."},"takeaway":"Observe quando uma exigência linguística funciona como imposição de pertencimento social.","key":"linguagens:L495","area":"linguagens","year":2024,"number":4,"answer":"A","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[3,4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma recusa editorial apesar dos elogios","steps":["A carta elogia a narrativa, mas reclama de todas as frases terminarem com um ponto de exclamação.","A passagem decisiva é pass on your manuscript, que, nesse contexto editorial, significa não aceitar o original.","A finalidade é comunicar a recusa de publicação, E; o motivo satírico não transforma a carta em pedido de revisão."],"alternatives":{"A":"O enredo recebe elogios; não é o objeto principal de questionamento da carta.","B":"A editora faz uma decisão editorial, não apenas confirma que recebeu o manuscrito.","C":"Embora mencione pontuação, não solicita uma nova versão revisada.","D":"Pass on, neste contexto, não significa transferir o livro a outra editora.","E":"A frase sobre a decisão difícil informa que a editora não publicará o romance."},"takeaway":"Em cartas e e-mails, encontre o ato comunicativo final, mesmo quando há elogios introdutórios.","key":"linguagens:L496","area":"linguagens","year":2024,"number":5,"answer":"E","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[3,4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Léxico regional como patrimônio","steps":["O livro registra expressões amazônicas e as camisetas as colocam em circulação com humor.","As duas iniciativas relacionam a fala regional a orgulho e pertencimento.","Seu objetivo comum é valorizar o repertório linguístico do Amazonas, E, não apenas vender produtos ou marcar diferenças."],"alternatives":{"A":"A existência de produtos não torna sua recomendação comercial a finalidade comum.","B":"A diferença entre falares é citada, mas o objetivo compartilhado é valorização.","C":"Só o livro envolve a pesquisa descrita; a homenagem a pesquisadores não une as propostas.","D":"O humor aparece nas camisetas, mas não resume a função documental do livro.","E":"Registro e divulgação positiva conferem visibilidade e valor ao falar amazonense."},"takeaway":"Compare a finalidade de todas as iniciativas; uma característica de só uma delas não basta.","key":"linguagens:L186","area":"linguagens","year":2024,"number":6,"answer":"E","subject":"Variação linguística","topic":"Variedades linguísticas, identidade e preconceito","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Minibiografias organizam trajetórias","steps":["Cada segmento apresenta uma atleta, sua entrada no esporte e a mudança de modalidade.","As conquistas integram a sequência individual, sem produzir uma classificação entre as atletas.","A finalidade é destacar trajetórias profissionais de paralímpicas brasileiras, C."],"alternatives":{"A":"Não se descrevem séries, frequências ou rotinas de treinamento.","B":"Os resultados são narrados, mas não há comparação sistemática de desempenho.","C":"As histórias de transição e conquistas constituem percursos profissionais individuais.","D":"Não é um guia técnico para escolher categorias adequadas a cada deficiência.","E":"O texto pode inspirar leitoras, mas não formula uma convocação a campeonatos."},"takeaway":"Identifique a organização do gênero: uma sequência de percursos de vida aponta para biografia.","key":"linguagens:L048","area":"linguagens","year":2024,"number":7,"answer":"C","subject":"Interpretação de texto e gêneros textuais","topic":"Gêneros textuais e finalidades comunicativas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Instrumentos mudam ao circular entre culturas","steps":["O cavaquinho brasileiro tem dimensões diferentes do minhoto.","No Havaí, instrumentos levados por madeirenses participam da origem do ukulele.","O percurso mostra adaptação cultural e novas identidades, B, e não reprodução imutável de uma forma portuguesa."],"alternatives":{"A":"Não se informa dependência de madeira ou outra matéria-prima europeia.","B":"Mudanças de caixa, tamanho e denominação acompanham novas apropriações culturais.","C":"A origem de exemplos não prova hegemonia portuguesa sobre toda a família de cordófonos.","D":"Circulação e adaptação não são apresentadas no texto como choque ou dominação.","E":"Nomes e características mudam, contrariando a ideia de fidelidade formal absoluta."},"takeaway":"Trocas culturais podem produzir recriação: origem não significa identidade fixa.","key":"linguagens:L595","area":"linguagens","year":2024,"number":8,"answer":"B","subject":"Artes","topic":"Música e patrimônio cultural","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O rendimento tem um custo mental","steps":["As histórias relacionam ansiedade e depressão ao ritmo competitivo, à exposição e ao afastamento familiar.","O comando pede causas do desequilíbrio, não uma característica biográfica comum.","A resposta são as pressões dos eventos e da mídia, E; a imagem heroica é parte desse contexto de cobrança."],"alternatives":{"A":"Atletas de nacionalidades diferentes sofrem problemas semelhantes; a nacionalidade não é causa.","B":"As modalidades variam e não são apresentadas como causadoras específicas dos transtornos.","C":"A proximidade etária não explica a relação causal exposta.","D":"A representação de herói é uma crítica importante, mas não reúne as pressões concretas citadas.","E":"Cobrança, calendário intenso e exposição midiática explicitam as causas destacadas."},"takeaway":"Não use desempenho ou renda como prova de saúde mental: observe as condições de trabalho.","key":"linguagens:L672","area":"linguagens","year":2024,"number":9,"answer":"E","subject":"Educação Física","topic":"Corpo, saúde e qualidade de vida","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O argumento a favor dos podcasts","steps":["O autor rejeita tanto a identificação com o rádio quanto a semelhança com redes dispersivas.","Seus exemplos cotidianos associam ouvir podcasts a aprender diferentes assuntos.","O benefício argumentado é a divulgação de conhecimento, C; o PhD é uma hipérbole, não um diploma real."],"alternatives":{"A":"Dispersão caracteriza as redes sociais no contraste do autor, não os podcasts.","B":"Ondas curtas são evocadas para negar a identificação direta com o rádio.","C":"A aprendizagem em atividades cotidianas exemplifica a circulação de conhecimento.","D":"O autor chama podcasts de antípodas das redes, destacando a oposição.","E":"A comparação inicial com renascimento do rádio é explicitamente recusada."},"takeaway":"Diferencie a opinião que um texto cita para refutar da tese que efetivamente defende.","key":"linguagens:L723","area":"linguagens","year":2024,"number":10,"answer":"C","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Do estigma ao legado linguístico","steps":["Inicialmente, a língua era inferiorizada pela origem e condição social dos falantes.","Depois, é reconhecida como vínculo com a descendência africana e transmitida como herança.","A preservação se relaciona à consolidação da identidade linguística, D, não à manutenção de uma função secreta."],"alternatives":{"A":"O trecho não aponta passagem à escrita como causa central de preservação.","B":"O reconhecimento da língua não demonstra ascensão de prestígio econômico dos falantes.","C":"A função de comunicação secreta na escravidão não permanece como explicação atual.","D":"Pertencimento, ancestralidade e transmissão às novas gerações fundamentam a preservação.","E":"A faixa de 21 a 60 anos é diversa e não explica por si a continuidade da língua."},"takeaway":"Línguas podem ser preservadas pelo valor identitário mesmo quando sua função social se transforma.","key":"linguagens:L265","area":"linguagens","year":2024,"number":12,"answer":"D","subject":"Variação linguística","topic":"História da língua e diversidade cultural","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Informação sobre pobreza menstrual","steps":["O texto organiza dados de pesquisas e consequências da falta de absorventes.","O foco está no problema e em seus efeitos sociais e escolares.","Esse predomínio informativo caracteriza função referencial: informar o impacto da pobreza menstrual, D."],"alternatives":{"A":"Não apresenta uma lista de soluções como propósito principal.","B":"Menstruação e gravidez são comparadas em um dado, mas não constituem a finalidade global.","C":"Não há comparação sistemática entre desempenho de homens e mulheres.","D":"Dados, fontes e consequências informam o leitor sobre o problema social.","E":"O texto não é um manual de autocuidado ou de higiene pessoal."},"takeaway":"Função referencial privilegia informações sobre o referente, ainda que também provoque reflexão.","key":"linguagens:L287","area":"linguagens","year":2024,"number":13,"answer":"D","subject":"Funções e figuras de linguagem","topic":"Funções da linguagem","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Variação não é defeito da língua","steps":["O encontro entre falantes revela diferentes nomes para produtos semelhantes.","A explicação recíproca permite construir entendimento.","As variedades são constitutivas do português brasileiro, C; o episódio não demonstra uma língua regional superior."],"alternatives":{"A":"A surpresa inicial é superada pela explicação: a compreensão não é impedida definitivamente.","B":"O texto valoriza diversidade, não estabelece superioridade do falar maranhense.","C":"As diferenças lexicais regionais integram a diversidade interna do português.","D":"As expressões funcionam socialmente sem depender de inclusão num dicionário.","E":"Variedades não existem apenas em situações coloquiais, embora o exemplo seja informal."},"takeaway":"Distinções entre variedades não equivalem a distinções entre quem sabe e quem não sabe falar.","key":"linguagens:L187","area":"linguagens","year":2024,"number":14,"answer":"C","subject":"Variação linguística","topic":"Variedades linguísticas, identidade e preconceito","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Possibilidade de acesso não é acesso garantido","steps":["O texto enumera benefícios e limitações da telemedicina.","Entre os benefícios está superar barreiras geográficas para pacientes de áreas remotas ou carentes.","B expressa esse potencial; aparelhos, infraestrutura e prontuário único não aparecem como resultados já garantidos."],"alternatives":{"A":"O prontuário unificado ainda está em discussão, não é uma disponibilidade consumada.","B":"Atendimento remoto pode alcançar pacientes em regiões com carência de assistência.","C":"A telemedicina não é descrita como fornecedora de aparelhos para exames.","D":"A interoperabilidade é discutida, mas o benefício social diretamente destacado é ampliar acesso.","E":"O texto afirma que muitos profissionais ainda carecem de infraestrutura."},"takeaway":"Diferencie projeto, potencial e realização efetiva: os tempos e modalidades verbais importam.","key":"linguagens:L724","area":"linguagens","year":2024,"number":15,"answer":"B","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Arte afro-brasileira e experiências diversas","steps":["A definição aceita artistas de diferentes origens raciais e nacionais.","O vínculo comum são experiências com a cultura negra, transformadas em produção estética.","D reúne vivências pessoais e referenciais de matriz africana, sem impor uniformidade."],"alternatives":{"A":"O envolvimento profundo de Carybé não é apresentado como estranhamento.","B":"A definição permite intercâmbio; não exige separar a matriz africana de outras culturas.","C":"A diversidade dos percursos não sustenta uma visão religiosa única.","D":"A produção emerge da relação singular entre experiência social e referências estéticas.","E":"Os exemplos não obedecem necessariamente a uma forma ou temática padronizada."},"takeaway":"Não reduza uma produção cultural à origem biológica ou nacional de quem a realiza.","key":"linguagens:L618","area":"linguagens","year":2024,"number":16,"answer":"D","subject":"Artes","topic":"História da arte e outras manifestações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Saúde também depende das condições de vida","steps":["O estudo relaciona atividade física e saúde mental.","A possibilidade de manter exercícios varia conforme renda e acesso a espaços seguros.","A perspectiva ampliada aparece na ligação entre determinantes socioeconômicos e prática corporal, D."],"alternatives":{"A":"Espaços importam, mas a opção não expressa a desigualdade socioeconômica destacada.","B":"Reconhecer benefício emocional da atividade, isoladamente, não explicita a abordagem ampliada.","C":"A quarentena é o contexto, mas não resume as diferenças sociais analisadas.","D":"Renda e condições territoriais influenciam as possibilidades de cuidar da saúde.","E":"O texto compara oportunidades, não garante estabilidade psicológica a toda pessoa do campo."},"takeaway":"Evite reduzir saúde a decisão individual quando o texto mostra desigualdade de condições.","key":"linguagens:L673","area":"linguagens","year":2024,"number":18,"answer":"D","subject":"Educação Física","topic":"Corpo, saúde e qualidade de vida","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A liberdade formal não apaga a exploração","steps":["A personagem compara seu conforto ao trabalho sem descanso nem remuneração de Sancha.","A descrição evidencia violência e desigualdade racial no período pós-abolição.","A crítica se dirige à exploração da força de trabalho negra, D, e não a uma disputa equilibrada de poder."],"alternatives":{"A":"A arte da personagem aparece no contraste, mas não é o alvo principal da denúncia.","B":"A moradia precária é um indício da exploração, não uma mudança habitacional analisada.","C":"O trecho não apresenta a ruptura de um projeto político de emancipação feminina.","D":"A jornada exaustiva, os maus-tratos e a ausência de pagamento sustentam a crítica.","E":"As posições são profundamente desiguais; não há uma disputa de poder equivalente entre grupos."},"takeaway":"Considere a permanência de relações de exploração depois da mudança do estatuto jurídico.","key":"linguagens:L456","area":"linguagens","year":2024,"number":19,"answer":"D","subject":"Literatura","topic":"Realismo e Naturalismo — Machado de Assis e outros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A repetição organiza a crônica","steps":["Coisa aparece em lembranças, comentários e versos citados.","Coisinha e coisar ampliam essa mesma rede lexical.","A repetição da palavra e de cognatos garante unidade temática por reiteração, C."],"alternatives":{"A":"Há intertextualidade, mas ela não é o recurso lexical que atravessa toda a progressão.","B":"Há reflexão sobre linguagem, mas o comando destaca como se mantém o tema.","C":"A cadeia lexical coisa/coisinha/coisar articula os diferentes exemplos.","D":"Conectores relacionam orações, mas não explicam o eixo temático recorrente.","E":"As retomadas pronominais sugeridas não constituem o recurso dominante da crônica."},"takeaway":"Coesão lexical inclui repetição produtiva: reiterar não é automaticamente um defeito.","key":"linguagens:L335","area":"linguagens","year":2024,"number":20,"answer":"C","subject":"Gramática a serviço do sentido","topic":"Classes de palavras, referenciação e efeitos de sentido","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O adorno tem função social e cosmológica","steps":["O texto informa que o uso de adornos depende da linhagem.","A imagem do diadema deve ser lida nesse contexto, e não apenas pela aparência das penas.","Compreendê-lo exige relacionar objeto ritual e papéis dos indivíduos na comunidade, E."],"alternatives":{"A":"O uso não é indiferenciado: há permissões ligadas à linhagem.","B":"As matérias naturais não se sobrepõem às relações humanas que atribuem sentido ao adorno.","C":"O texto não afirma uma mudança contínua das concepções do universo.","D":"Não se trata de confundir identidade pessoal e coletiva, mas de compreender sua articulação.","E":"O objeto comunica pertencimento, direitos, deveres e concepções de mundo."},"takeaway":"Em arte indígena, não isole estética, cosmologia e organização social.","key":"linguagens:L619","area":"linguagens","year":2024,"number":21,"answer":"E","subject":"Artes","topic":"História da arte e outras manifestações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A palavra apresentada como arma","steps":["Minha palavra vale um tiro aproxima linguagem e combate.","Munição e ataque cardíaco do verso continuam a associação entre criação verbal e enfrentamento.","Ao falar da própria palavra, o rap usa metalinguagem para afirmar combate e insubordinação, C."],"alternatives":{"A":"A leitura não se concentra numa associação direta entre justiça e valores históricos negativos.","B":"Os termos bélicos existem, mas a opção não explica o foco explícito na própria palavra.","C":"O texto tematiza o poder de sua linguagem, convertendo o verso em instrumento de enfrentamento.","D":"As oposições de identidade participam do texto, mas não explicam tão diretamente a palavra-arma.","E":"A imortalidade é uma imagem secundária, não o procedimento central destacado."},"takeaway":"Metalinguagem não aparece só em dicionários: uma canção também pode refletir sobre sua palavra.","key":"linguagens:L307","area":"linguagens","year":2024,"number":22,"answer":"C","subject":"Funções e figuras de linguagem","topic":"Figuras de linguagem e efeitos expressivos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O mas introduz ressalvas","steps":["A resenha reconhece qualidades de personagens e trilha sonora.","Repetidamente, mas conduz a limites: problemas persistentes, falhas de adaptação e pressa no final.","As adversativas introduzem ressalvas aos elogios, B, sem anular a avaliação positiva geral."],"alternatives":{"A":"Este que vos fala e penso crítico tornam a opinião visível, não impessoal.","B":"Os conectores adversativos contrapõem avaliação favorável e restrições.","C":"A interlocução não é o mecanismo sintático que insere as críticas.","D":"As falhas não são apenas suavizadas por eufemismos; são explicitamente contrapostas.","E":"Não há uma antítese central e exclusiva entre roteiro frágil e trilha bela."},"takeaway":"Uma adversativa pode limitar um elogio sem transformar todo o texto em rejeição.","key":"linguagens:L336","area":"linguagens","year":2024,"number":23,"answer":"B","subject":"Gramática a serviço do sentido","topic":"Classes de palavras, referenciação e efeitos de sentido","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Escrever como se fala?","steps":["Paulo critica uma redação por soar artificial e distante da fala.","Gondim sustenta que literatura exige uma linguagem diferente da conversa.","O debate contrapõe preciosismo e coloquialidade, D; o trecho não resolve a questão por uma regra simples sobre norma-padrão."],"alternatives":{"A":"O contraste não é entre arte e norma-padrão, mas entre escrita afetada e expressão natural.","B":"Não se limita a um dialeto social de baixo prestígio.","C":"Um personagem questiona a distância entre fala e escrita, mas a discussão não é uma defesa consensual.","D":"As falas explicitam o choque entre linguagem empolada e uso cotidiano.","E":"O desentendimento decorre de concepções de estilo, não do uso da norma culta por si."},"takeaway":"Separe norma-padrão, formalidade e preciosismo: não são a mesma coisa.","key":"linguagens:L221","area":"linguagens","year":2024,"number":24,"answer":"D","subject":"Variação linguística","topic":"Oralidade, registros e adequação comunicativa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Luz e pincelada em Visconti","steps":["Observe a paisagem luminosa e as pinceladas que sugerem folhagens, figuras e atmosfera.","A pintura privilegia a impressão visual e as variações da luz, sem decomposição geométrica dominante.","Esses efeitos remetem ao impressionismo, C, e não basta haver uma cena cotidiana para escolher Realismo."],"alternatives":{"A":"Não há exaltação de máquinas, velocidade ou progresso própria do ideário futurista.","B":"As formas não são fragmentadas em planos geométricos como na proposta cubista.","C":"A luminosidade e a aparência fugaz da cena aproximam a obra da estética impressionista.","D":"A cena não é organizada como sonho ou imagem do inconsciente.","E":"Cotidiano é um tema compartilhável por estilos; o tratamento da luz é mais decisivo aqui."},"takeaway":"Identifique o modo de representar, não somente o assunto representado, ao reconhecer uma estética.","key":"linguagens:L620","area":"linguagens","year":2024,"number":25,"answer":"C","subject":"Artes","topic":"História da arte e outras manifestações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Um estereótipo limita a participação","steps":["A presença feminina nas lutas aumenta fora da escola.","Na escola, estudantes ainda associam essas práticas ao masculino e as julgam inadequadas às meninas.","A barreira explicitada é a masculinização da modalidade, B; a exclusão do conteúdo pode ser consequência."],"alternatives":{"A":"A questão não atribui o problema apenas à transformação das lutas em esporte.","B":"A associação cultural entre luta e masculinidade restringe interesse e participação das meninas.","C":"A transmissão de lutas femininas aparece como sinal de maior visibilidade, não como causa da barreira.","D":"Há implicações pedagógicas, mas o mecanismo explicitado é o estereótipo de gênero.","E":"A marginalização na disciplina é possível efeito das tensões, não a explicação central indicada."},"takeaway":"Em relações de gênero, diferencie uma capacidade corporal de um estereótipo social sobre quem pode praticar.","key":"linguagens:L656","area":"linguagens","year":2024,"number":26,"answer":"B","subject":"Educação Física","topic":"Esporte, inclusão e práticas corporais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Empatia é reconhecer a experiência do outro","steps":["A autora demonstra afeto por seus leitores jovens.","Empatia aparece de modo mais preciso quando reconhece a dificuldade de ser jovem nas condições atuais.","Sinto que é mais complicado ser jovem hoje, C, explicita essa compreensão, enquanto beijos e carinhos expressam afeto."],"alternatives":{"A":"Relatar cartas recebidas informa uma circunstância, sem ainda reconhecer a dificuldade alheia.","B":"Ficar no céu expressa a emoção da autora com o reconhecimento recebido.","C":"A frase procura compreender a situação vivida pela juventude a quem se dirige.","D":"O desejo de carinho é acolhedor, mas não explicita tão precisamente a tomada de perspectiva.","E":"A crítica à sociedade é ampla e não nomeia diretamente a experiência particular do leitor."},"takeaway":"Não trate como sinônimos automáticos empatia, carinho, alegria e elogio.","key":"linguagens:L146","area":"linguagens","year":2024,"number":27,"answer":"C","subject":"Interpretação de texto e gêneros textuais","topic":"Intertextualidade e relações entre textos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Recontar Capitu com outra voz","steps":["O autor relembra sua leitura do romance e critica a palavra autoritária de Bentinho.","Apresenta assim uma reação subjetiva ao enredo e ao silenciamento da personagem.","No fim, anuncia que Capitu terá seu discurso e sua verdade: contextualização subjetiva seguida do novo foco narrativo, E."],"alternatives":{"A":"O autor não reafirma o ponto de vista de Bentinho; busca confrontar seu monopólio da narração.","B":"A crítica literária é mencionada, mas não constitui a organização principal do anúncio.","C":"Ele não pretende negar os fatos centrais da história, e sim mudar a voz que os apresenta.","D":"Justifica sua escolha e a mantém, não a reconsidera ao final.","E":"A memória de leitura conduz ao anúncio de uma narração assumida por Capitu."},"takeaway":"Intertextualidade pode alterar quem tem direito à voz, não apenas repetir personagens ou episódios.","key":"linguagens:L089","area":"linguagens","year":2024,"number":28,"answer":"E","subject":"Interpretação de texto e gêneros textuais","topic":"Argumentação e pontos de vista","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O termo adotivo e o estigma social","steps":["O narrador associa a expressão técnica à tentativa de limpar sentidos indesejáveis.","As reações solenes e a pergunta filho de quem revelam expectativas sobre filiação.","A adoção é pensada em relação a representações sociais estigmatizadas da parentalidade, A, e não só como dúvida privada entre irmãos."],"alternatives":{"A":"As marcas de pesar e o desconforto com a origem apontam para um estigma sobre filiação.","B":"O trecho não formula uma necessidade de obter autorização ou aprovação dos desconhecidos.","C":"Os interlocutores citados não são necessariamente membros do núcleo familiar.","D":"A tecnicidade é um recurso da reflexão, mas o problema maior é a representação social da adoção.","E":"A inquietação é narrada por um irmão, mas não é apresentada como universal ou própria de toda fraternidade."},"takeaway":"Observe como reações de linguagem e de convivência revelam valores sociais naturalizados.","key":"linguagens:L365","area":"linguagens","year":2024,"number":29,"answer":"A","subject":"Literatura","topic":"Literatura contemporânea (pós-1960)","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Arte que abala certezas","steps":["Graciliano recusa a acusação de que representar miséria desqualifica a arte.","Prata critica obras que apenas reforçam certezas e escondem contradições.","Os dois valorizam o caráter desestabilizador da arte, D: expor problemas e defeitos, em vez de oferecer conforto simplificador."],"alternatives":{"A":"Só afirmar a dignidade do ofício não recupera a posição comum sobre o efeito da arte.","B":"Prata critica, e não defende, o reforço confortável das crenças do público.","C":"A pobreza é central na carta, mas não resume os exemplos e a tese de Prata.","D":"A arte pode incomodar, tornar contradições visíveis e deixar as certezas em suspenso.","E":"Mudanças na produção são discutidas sobretudo no segundo texto; não são a tese comum."},"takeaway":"Ao comparar teses, procure a proposição compartilhada, não um assunto presente em apenas um texto.","key":"linguagens:L090","area":"linguagens","year":2024,"number":30,"answer":"D","subject":"Interpretação de texto e gêneros textuais","topic":"Argumentação e pontos de vista","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A ironia de um baile às vésperas da República","steps":["O comando situa a festa como o último baile do Império.","Flora imagina o futuro poder de uma imperatriz como liberdade para recolher-se à música e à contemplação.","O contraste entre esse devaneio e o fim próximo do regime ironiza a alienação da elite, B."],"alternatives":{"A":"O trecho não anuncia esperança na República como foco da ironia.","B":"A personagem sonha com continuidade e conforto dinástico sem perceber a crise próxima.","C":"Contemplar não é o alvo isolado; importa o descompasso com a transformação política.","D":"Não se narra hostilidade explícita entre a população e a nobreza naquela cena.","E":"O devaneio não tem como tema central casamento ou realização amorosa burguesa."},"takeaway":"Na ironia histórica, compare o que a personagem sabe com o contexto informado ao leitor.","key":"linguagens:L457","area":"linguagens","year":2024,"number":31,"answer":"B","subject":"Literatura","topic":"Realismo e Naturalismo — Machado de Assis e outros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O carinho atravessa a fragilidade","steps":["Andador, escada e alimentos em pedaços mostram o declínio físico.","A força do gesto de Marília é reconhecida como carinho acumulado por anos de convivência.","A sensibilidade lírica se concentra na atmosfera de afeto, B, não apenas nas limitações funcionais."],"alternatives":{"A":"As adaptações são contexto; a narradora inclusive rejeita algumas delas.","B":"Os gestos de cuidado e a leitura afetiva de sua força dão sentido lírico ao trecho.","C":"A dependência existe, mas a relação não se reduz a necessidade de assistência.","D":"A rotina organiza a cena, sem ser o centro de sua emoção.","E":"A narradora não simplesmente aceita todas as restrições; preserva desejos de autonomia."},"takeaway":"Em texto literário, diferencie as condições da cena do sentimento que organiza sua representação.","key":"linguagens:L366","area":"linguagens","year":2024,"number":32,"answer":"B","subject":"Literatura","topic":"Literatura contemporânea (pós-1960)","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Deixar a roupa partir para doá-la","steps":["A campanha de agasalho mostra uma pessoa segurando uma roupa com a frase Vou deixar que você se vá.","A despedida figurada se conecta à doação e ao pedido de roupas que possam aquecer outras pessoas.","A finalidade é relacionar doação a desapego, D; a comparação afetiva é um meio, não o objetivo final da campanha."],"alternatives":{"A":"Não se pede descartar peças defeituosas, mas doar itens que possam ser usados.","B":"Doação para uso por outras pessoas não é reciclagem de materiais.","C":"O cartaz estimula circulação solidária da roupa, não apenas sua conservação.","D":"O desapego de uma peça pessoal é convertido em ajuda a quem precisa.","E":"A comparação com despedida participa da estratégia, mas não expressa sozinha a finalidade social."},"takeaway":"Em publicidade social, separe o recurso expressivo do comportamento que se deseja incentivar.","key":"linguagens:L049","area":"linguagens","year":2024,"number":33,"answer":"D","subject":"Interpretação de texto e gêneros textuais","topic":"Gêneros textuais e finalidades comunicativas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Um teclado que acolhe outras escritas","steps":["A professora precisa produzir letras e diacríticos ausentes dos teclados comuns.","O aplicativo facilita essas combinações e o registro de línguas originárias.","Sua contribuição é democratizar o registro escrito, B: ele não cria os fonemas, mas permite representá-los."],"alternatives":{"A":"Fonemas são unidades sonoras da língua; o aplicativo facilita sua representação gráfica.","B":"Acesso a letras e diacríticos permite escrever com menos obstáculos em diferentes línguas.","C":"O jogo tem instruções em português a traduzir; não é apresentado como criação indígena.","D":"O foco é a ferramenta de escrita, não a divulgação de métodos de tradução.","E":"O objetivo relatado é escrever na língua materna indígena, não aprender português."},"takeaway":"Não confunda língua, som e escrita: uma limitação do teclado não é uma limitação da língua.","key":"linguagens:L725","area":"linguagens","year":2024,"number":34,"answer":"B","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O dinheiro invade o vínculo amoroso","steps":["Aurélia rejeita a declaração romântica e chama o marido de homem vendido.","Mercado, comprei e cem contos de réis transformam o casamento em negócio.","O conflito revela interferência da riqueza sobre o amor, D, no romance urbano romântico."],"alternatives":{"A":"A denúncia não se apresenta como uma formulação de igualdade de direitos entre gêneros.","B":"O beijo inicialmente idealizado é deslocado pela acusação de interesse financeiro.","C":"Há crítica social, mas a alternativa é ampla e não identifica o eixo dinheiro/casamento.","D":"A compra metafórica do marido explicita a mercantilização do vínculo amoroso.","E":"A alternativa é genérica e não contempla a acusação de interesse econômico."},"takeaway":"Não responda apenas Romantismo = idealização: o romance urbano também expõe tensões sociais.","key":"linguagens:L471","area":"linguagens","year":2024,"number":35,"answer":"D","subject":"Literatura","topic":"Romantismo","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Semelhanças formais através do tempo","steps":["As duas cabeças reduzem detalhes e usam formas alongadas e estilizadas.","As datas e contextos diferem, mas a comparação permite reconhecer afinidades visuais.","A conclusão sustentada é persistência de padrões estéticos em épocas e culturas distintas, D; não prova influência direta."],"alternatives":{"A":"A semelhança não é, sozinha, prova documental de valorização ou cópia da obra antiga.","B":"Não se compara desenvolvimento técnico nem resistência a novas tecnologias.","C":"Mármore e calcário não impõem necessariamente aquela mesma solução formal.","D":"Formas e simplificações afins reaparecem apesar da distância histórica e cultural.","E":"A ausência de detalhes não é exclusiva da arte tradicional popular."},"takeaway":"Semelhança visual permite comparação; para afirmar influência causal, seriam necessárias outras evidências.","key":"linguagens:L567","area":"linguagens","year":2024,"number":36,"answer":"D","subject":"Artes","topic":"Arte contemporânea e linguagens visuais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A argumentação fala por meio de canções","steps":["O texto incorpora versos e expressões reconhecíveis de diversas músicas.","As referências acompanham situações de dor, mudança e recuperação emocional.","A intertextualidade, C, demonstra na própria escrita a presença da música no cotidiano."],"alternatives":{"A":"Dor e alegria são momentos diferentes do percurso, não uma contradição que organiza a persuasão.","B":"A metáfora citada pertence a uma canção e integra uma rede maior de referências.","C":"O resgate de letras estabelece diálogo entre o texto e o repertório musical do leitor.","D":"A enumeração de ritmos existe, mas não explica a rede de versos incorporados.","E":"As palavras não são todas hipérboles; o procedimento abrangente é a referência a outras canções."},"takeaway":"Um recurso pode conter figuras locais: escolha o que explica a estratégia do texto como um todo.","key":"linguagens:L308","area":"linguagens","year":2024,"number":37,"answer":"C","subject":"Funções e figuras de linguagem","topic":"Figuras de linguagem e efeitos expressivos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Viajar sem conseguir deixar de ser si","steps":["O poema começa com deslocamentos e bagagens concretas.","Nos versos finais, o destino desejado seria um lugar onde as próprias pessoas não estivessem.","Essa impossibilidade transforma a viagem em metáfora de fuga da própria identidade, B."],"alternatives":{"A":"Encontros aparecem, mas os versos finais deslocam o foco para a relação consigo mesmas.","B":"O desejo de chegar onde não se está sugere escapar do próprio eu.","C":"Não se afirma que o destino seja geograficamente desconhecido ou inexplorado.","D":"O centro não é buscar aventura ou experiência inédita, mas afastar-se de si.","E":"Não há um projeto literal de abandonar a sociedade ou todo contato humano."},"takeaway":"Releia o fechamento do poema: ele pode modificar o sentido de todas as imagens anteriores.","key":"linguagens:L367","area":"linguagens","year":2024,"number":38,"answer":"B","subject":"Literatura","topic":"Literatura contemporânea (pós-1960)","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Desvio da norma como escolha artística","steps":["O texto chama de falar errado formas como nóis vai, mas as reconhece como parte de uma arte deliberada.","O preconceito toma a divergência da norma-padrão como inferioridade da linguagem.","E identifica essa divergência; não significa que a variedade não tenha regras ou valor expressivo."],"alternatives":{"A":"O fenômeno não se limita a uma linguagem exclusiva de comediantes.","B":"A identificação popular e o sucesso contrariam a ideia de incompreensão das canções.","C":"O texto enfatiza estilo consciente, e não ausência de estilo.","D":"As formas ajudam a produzir identidade e expressão poética, não restringem necessariamente a criação.","E":"A transgressão da norma-padrão é indevidamente usada como critério de inferiorização."},"takeaway":"Diferencie desvio em relação à norma-padrão de falta de sistema, sentido ou competência linguística.","key":"linguagens:L188","area":"linguagens","year":2024,"number":39,"answer":"E","subject":"Variação linguística","topic":"Variedades linguísticas, identidade e preconceito","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Festa e lógica de competição esportiva","steps":["O festival apresenta torcidas rivais, identificação por cores, títulos e gritos de guerra.","Esses traços também estruturam o universo do esporte competitivo.","A apropriação aproxima a manifestação folclórica do esporte, D, sem fazer com que deixe de ser cultura."],"alternatives":{"A":"A arena é parte do evento, mas o comando reúne rivalidade e comportamento das torcidas.","B":"O texto não atribui a transformação principalmente à valorização dos turistas.","C":"A rivalidade acontece durante o festival, não apenas nas interações posteriores.","D":"As práticas de torcida e disputa por títulos produzem uma aproximação com o esporte.","E":"Garanchosos identificam uma posição entre torcidas, não uma autoria musical demonstrada."},"takeaway":"Práticas corporais e manifestações culturais podem compartilhar formas de organização e pertencimento.","key":"linguagens:L657","area":"linguagens","year":2024,"number":40,"answer":"D","subject":"Educação Física","topic":"Esporte, inclusão e práticas corporais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Informação de saúde para reconhecer sinais","steps":["A reportagem corrige a crença de que apenas mulheres têm câncer de mama.","Depois apresenta fatores de risco e sinais de alerta, como caroço e retração.","A contribuição direta é chamar atenção para sinais indicadores da doença, A, sem oferecer diagnóstico individual."],"alternatives":{"A":"Caroço e retração do mamilo são exemplos de sinais suspeitos destacados na reportagem.","B":"Os dados de casos não mostram uma série temporal capaz de calcular crescimento.","C":"Não são descritos procedimentos de exames diagnósticos específicos.","D":"A genética aparece como fator de risco, não como um conjunto de mitos a refutar.","E":"Outubro Rosa é contexto, mas conhecer o calendário não é o principal alerta informativo."},"takeaway":"Informação sobre sinais e fatores de risco não substitui avaliação médica nem confirma diagnóstico.","key":"linguagens:L003","area":"linguagens","year":2024,"number":41,"answer":"A","subject":"Interpretação de texto e gêneros textuais","topic":"Recursos expressivos e construção de sentidos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma obra que inclui o inesperado","steps":["A lata foi preparada como câmera e depois esquecida.","A exposição de oito anos não foi o resultado de um controle contínuo e planejado.","O experimento mostra que uma produção artística pode resultar do acaso, E; não diz que toda arte depende dele."],"alternatives":{"A":"A técnica simples produziu um registro extraordinário, não demonstra apenas limitação.","B":"Apreciar a natureza não é apresentado como algo impossível sem fotografá-la.","C":"A relação com ciência existe, mas não explica o papel decisivo do esquecimento.","D":"A câmera caseira tem interesse, mas a conclusão central é o resultado imprevisto.","E":"Um projeto esquecido gerou uma imagem que incorporou o acontecimento não planejado."},"takeaway":"Diferencie intenção inicial e resultado: processos artísticos podem acolher contingências.","key":"linguagens:L579","area":"linguagens","year":2024,"number":43,"answer":"E","subject":"Artes","topic":"Teatro e performance","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O programa olímpico é historicamente construído","steps":["O texto lista modalidades incorporadas em épocas diferentes.","A inclusão do break é associada à aproximação de jovens urbanos e de seus modos de se exercitar.","A mudança mostra adaptação às demandas de seu tempo, E, e não abandono de toda identidade esportiva."],"alternatives":{"A":"Há modalidades de aventura entre os exemplos, mas o break não se explica só por isso.","B":"O texto enfatiza mudança, não manutenção de um padrão imutável.","C":"Incluir uma dança não transforma todas as modalidades esportivas em dança.","D":"A decisão incorpora uma prática cultural, em vez de afastar-se da cultura.","E":"Novas práticas e públicos influenciam o reconhecimento institucional de modalidades."},"takeaway":"Categorias como esporte e cultura mudam historicamente; não trate seus limites como naturais e eternos.","key":"linguagens:L697","area":"linguagens","year":2024,"number":44,"answer":"E","subject":"Educação Física","topic":"Cultura corporal, jogos e lazer","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ler memes exige olhar crítico","steps":["A professora identifica compartilhamentos feitos sem compreender as mensagens.","A análise em aula revela usos de humor, imagens e palavras para manipular informação.","A crítica é à divulgação de informação manipulada, B; não à existência de memes ou ao uso de tecnologias na educação."],"alternatives":{"A":"A solução discutida é letramento crítico, não apenas fiscalização dos aplicativos infantis.","B":"Checagem e interpretação procuram enfrentar informação falsa ou manipulada nas postagens.","C":"As ferramentas digitais são usadas positivamente na proposta pedagógica.","D":"O humor não é condenado em si; o problema é a circulação irrefletida de conteúdos.","E":"Objetivos políticos não são, por si só, sinônimos de mentira ou manipulação."},"takeaway":"Avalie intenção, contexto e evidências antes de compartilhar, inclusive quando a mensagem parece apenas engraçada.","key":"linguagens:L726","area":"linguagens","year":2024,"number":45,"answer":"B","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2024.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
